<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';
import {useQuery} from '@tanstack/vue-query';
import {request} from '../../api/client';
import {permissions,message} from '../sites/data';
import {when} from '../certificates/contracts';
interface Enrollment {id:string;principal:{id:string;names:string[];purpose:string;directory:string;expires:string;disabled:boolean};binding_state:string;binding_expires?:string}
interface Issued {issuer:string;serial:string;principal_id:string;names:string[];purpose:string;not_before:string;not_after:string;revoked_at?:string;reason?:number}
interface EAB {kid:string;hmac:string;directory:string;expires:string}
interface Audit {id:string;actor_id:string;action:string;occurred_at:string}
const {isAdmin}=permissions(),audit=useQuery({queryKey:['pki-audit'],queryFn:()=>request<{items:Audit[]}>('/audit?limit=100&offset=0'),enabled:isAdmin,refetchOnWindowFocus:true}),query=useQuery({queryKey:['pki-identities'],queryFn:()=>request<{enrollments:Enrollment[];certificates:Issued[];directories:Record<string,string>}>('/pki/management'),enabled:isAdmin,refetchOnWindowFocus:true}),names=ref(''),purpose=ref('serverAuth'),expires=ref(''),code=ref(''),eab=ref<EAB>(),busy=ref(false),error=ref(''),notice=ref('');
function dismiss(){eab.value=undefined;code.value=''}
onMounted(()=>window.addEventListener('pagehide',dismiss));onUnmounted(()=>{dismiss();window.removeEventListener('pagehide',dismiss)});
async function perform(fn:()=>Promise<void>){dismiss();busy.value=true;error.value='';notice.value='';try{await fn();await Promise.all([query.refetch(),audit.refetch()])}catch(e){error.value=message(e)}finally{code.value='';busy.value=false}}
// Capture the proof before clearing old one-time material. No mutation response
// containing EAB is inserted into TanStack Query, Pinia, or browser storage.
function authorize(){const proof=code.value;void perform(async()=>{await request('/pki/grants',{names:names.value.split(/[\s,]+/).filter(Boolean),purpose:purpose.value,directory:purpose.value==='serverAuth'?'server':'client',expires:new Date(expires.value).toISOString(),totp_code:proof});notice.value='身份授权已提交，请使用新的动态验证码创建一次性 EAB。'})}
function issue(g:Enrollment){const proof=code.value;void perform(async()=>{eab.value=await request<EAB>('/pki/grants/'+g.id+'/eab',{totp_code:proof})})}
function disable(g:Enrollment){const proof=code.value;void perform(async()=>{await request('/pki/principals/'+g.principal.id+'/disable',{totp_code:proof});notice.value='身份已停用，禁止后续签发；现有证书须单独吊销。'})}
function revoke(c:Issued){const proof=code.value;void perform(async()=>{await request('/pki/issuers/'+encodeURIComponent(c.issuer)+'/certificates/'+encodeURIComponent(c.serial)+'/revoke',{totp_code:proof,reason:0});notice.value='单张证书吊销已提交权威状态；标准 OCSP/CRL 缓存和已建立连接有各自生命周期。'})}
</script>
<template><section><h1>内部身份</h1><p>首次人工授权后，创建有效期最长 15 分钟、单次消费的 EAB。客户端使用未修改的标准 ACME v2 目录。此管理页面不接受 CSR 或代理签发。</p><p v-if="!isAdmin">当前角色没有全局内部身份管理权限。</p><p v-if="error||query.error.value" role="alert">{{error||message(query.error.value)}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="isAdmin"><button @click="dismiss();query.refetch()" :disabled="busy">刷新身份与吊销状态</button><p v-for="(url,kind) in query.data.value?.directories" :key="kind">{{kind}} 标准目录：<span class="mono">{{url}}</span></p><label>身份操作动态验证码<input v-model="code" type="password" autocomplete="off" inputmode="numeric" maxlength="6"></label>
<section v-if="eab" role="alert" class="panel" data-testid="one-time-eab"><h2>一次性 EAB（仅此创建响应）</h2><p>关闭或离开此页后无法恢复。重新创建会废止旧值；请妥善传给标准客户端，不要放入日志。</p><dl><dt>Key ID</dt><dd>{{eab.kid}}</dd><dt>HMAC</dt><dd class="mono">{{eab.hmac}}</dd><dt>目录</dt><dd>{{query.data.value?.directories[eab.directory]}}</dd><dt>到期</dt><dd>{{when(eab.expires)}}</dd></dl><button @click="dismiss">已保存，清除一次性 EAB</button></section>
<form @submit.prevent="authorize" class="panel"><h2>授权新身份</h2><fieldset :disabled="busy"><label>身份 DNS 名称（每行一个）<textarea v-model="names" required/></label><label>身份用途<select v-model="purpose"><option value="serverAuth">serverAuth 内部服务器</option><option value="clientAuth">clientAuth 内部客户端</option></select></label><label>身份授权到期<input v-model="expires" type="datetime-local" required></label><button :disabled="code.length!==6">提交人工授权</button></fieldset></form>
<article v-for="g in query.data.value?.enrollments||[]" :key="g.id" class="panel" :data-testid="'principal-'+g.principal.id"><h2>{{g.principal.names.join(', ')}}</h2><p>{{g.principal.purpose}} · {{g.principal.disabled?'已停用':(new Date(g.principal.expires).getTime()<=Date.now()?'已过期':'已授权')}} · 授权到期 {{when(g.principal.expires)}}</p><p>EAB 状态 {{({not_issued:'尚未创建',available:'可消费',consumed:'已单次消费',expired:'已过期'} as Record<string,string>)[g.binding_state]}} · 到期 {{when(g.binding_expires)}}</p><button :disabled="busy||g.principal.disabled||code.length!==6" @click="issue(g)">创建/替换一次性 EAB</button><button :disabled="busy||g.principal.disabled||code.length!==6" @click="disable(g)">停用身份</button></article>
<h2>已签证书与权威吊销状态</h2><article v-for="c in query.data.value?.certificates||[]" :key="c.issuer+'/'+c.serial" class="panel" :data-testid="'issued-'+c.serial"><h3>{{c.names.join(', ')}}</h3><p>{{c.purpose}} · 颁发者 {{c.issuer}} · 序列号 {{c.serial}}</p><p>有效期 {{when(c.not_before)}} 至 {{when(c.not_after)}}</p><p>{{c.revoked_at?'已吊销 '+when(c.revoked_at):'未吊销'}} · 身份 {{c.principal_id}}</p><button :disabled="busy||!!c.revoked_at||code.length!==6" @click="revoke(c)">吊销单张证书</button></article>
<h2>近期安全操作审计</h2><p v-if="audit.error.value" role="alert">{{message(audit.error.value)}}</p><ul><li v-for="a in (audit.data.value?.items||[]).filter(a=>a.action.startsWith('pki.')||a.action.startsWith('certificates.'))" :key="a.id">{{when(a.occurred_at)}} · {{a.action}} · 操作者 {{a.actor_id}}</li></ul><router-link to="/">会话概览</router-link><p>这里只显示最近 100 条审计中的证书/PKI 操作。身份和已签证书列表最多各 1000 项。</p></template></section></template>
